const input = $input.all();

if (input.length !== 2) {
  throw new Error('Esperados dois resultados WF-04.');
}

const seen = new Set();

for (const item of input) {

  const r = item.json;

  if (
    r.schema_version !== '1.0' ||
    r.environment !== 'LAB' ||
    r.processor !== 'WF-04' ||
    r.fixture_type !== 'MOCK_AI_RESPONSE' ||
    r.dispatch_status !== 'MOCK_ONLY' ||
    r.real_ollama_call !== false ||
    r.real_execution_started !== false ||
    r.notification_sent !== false ||
    r.ready_for_operational_dispatch !== false
  ) {
    throw new Error('Contrato ou ambiente invalido.');
  }

  if (
    !Number.isInteger(r.queue_id) ||
    !r.investigation_id ||
    r.source_event_id !== 'LAB-0001' ||
    !Number.isInteger(r.investigation_version)
  ) {
    throw new Error('Identidade da investigacao invalida.');
  }

  if (
    !r.provenance ||
    r.provenance.version !== r.investigation_version ||
    !/^[a-f0-9]{64}$/.test(
      r.provenance.content_signature || ''
    )
  ) {
    throw new Error('Proveniencia invalida.');
  }

  if (seen.has(r.queue_id)) {
    throw new Error('Queue ID duplicado.');
  }

  seen.add(r.queue_id);

  if (r.investigation_version === 1) {

    if (
      r.queue_id !== 12 ||
      r.status !== 'SKIPPED' ||
      r.ai_executed !== false ||
      r.requires_human_review !== false ||
      r.analysis !== null
    ) {
      throw new Error('Versao historica invalida.');
    }

  } else if (r.investigation_version === 2) {

    if (
      r.queue_id !== 13 ||
      r.status !== 'ANALYSIS_COMPLETED' ||
      r.ai_executed !== true ||
      r.requires_human_review !== true ||
      !r.analysis
    ) {
      throw new Error('Resultado atual invalido.');
    }

    const a = r.analysis;

    for (const key of ['summary', 'assessment']) {
      if (
        typeof a[key] !== 'string' ||
        !a[key].trim()
      ) {
        throw new Error('Texto obrigatorio ausente: ' + key);
      }
    }

    for (
      const key of [
        'evidence_ids',
        'limitations',
        'review_actions'
      ]
    ) {
      if (
        !Array.isArray(a[key]) ||
        !a[key].every(v => typeof v === 'string')
      ) {
        throw new Error('Lista de analise invalida: ' + key);
      }
    }

    const ids = [...new Set(a.evidence_ids)];

    if (
      ids.length !== 2 ||
      !ids.includes('LAB-EV-001') ||
      !ids.includes('LAB-EV-002')
    ) {
      throw new Error('Evidencias inesperadas.');
    }

  } else {

    throw new Error('Versao inesperada neste fixture LAB.');

  }

