}

return input;

return $input.all().map(item => {

  const r = item.json;

  if (r.contract_validation !== 'VALID') {
    throw new Error('Contrato nao validado.');
  }

  const eligible = (
    r.investigation_version === 2 &&
    r.status === 'ANALYSIS_COMPLETED' &&
    r.requires_human_review === true
  );

  return {
    json: {
      ...r,

      decision: {
        eligible_for_report: eligible,
        target_workflow: eligible ? 'WF-05' : null,
        reason: eligible
          ? 'Analise MOCK validada para teste do relatorio.'
          : 'Versao historica ignorada.'
      },

      integration_mode: 'MOCK_SNAPSHOT',

      ready_for_operational_dispatch: false,
      real_ollama_call: false,
      notification_sent: false
    }
  };
});

const items = $input.all();

if (items.length !== 2) {
  throw new Error('Esperados dois resultados WF-04.');
}

const results = items.map(item => item.json);

for (const r of results) {

  if (
    r.schema_version !== '1.0' ||
    r.environment !== 'LAB' ||
    r.processor !== 'WF-04' ||
    r.contract_validation !== 'VALID' ||
    r.fixture_type !== 'MOCK_AI_RESPONSE' ||
    r.integration_mode !== 'MOCK_SNAPSHOT' ||
    r.dispatch_status !== 'MOCK_ONLY' ||
    r.real_ollama_call !== false ||
    r.notification_sent !== false ||
    r.ready_for_operational_dispatch !== false ||
    !r.provenance ||
    r.provenance.version !== r.investigation_version
  ) {
    throw new Error('Resultado WF-04 nao autorizado.');
  }
}

const versions = results.map(
  r => r.investigation_version
);

if (
  versions.filter(v => v === 1).length !== 1 ||
  versions.filter(v => v === 2).length !== 1
) {
  throw new Error('Versoes 1 e 2 obrigatorias.');
}

const historical = results.find(
  r => r.investigation_version === 1
);

const current = results.find(
  r => r.investigation_version === 2
);

if (
  historical.investigation_id !== current.investigation_id ||
  historical.source_event_id !== current.source_event_id ||
  historical.queue_id !== 12 ||
  current.queue_id !== 13
) {
  throw new Error('Identidade da investigacao divergente.');
}

if (
  historical.status !== 'SKIPPED' ||
  historical.ai_executed !== false ||
  historical.analysis !== null ||
  historical.decision?.eligible_for_report !== false ||
  historical.decision?.target_workflow !== null
) {
  throw new Error('Historico nao foi bloqueado.');
}

if (
  current.status !== 'ANALYSIS_COMPLETED' ||
  current.requires_human_review !== true ||
  current.decision?.eligible_for_report !== true ||
  current.decision?.target_workflow !== 'WF-05'
) {
  throw new Error('Versao atual nao autorizada.');
}

// Nao reconstruir artificialmente a analise.
