) {
  throw new Error('Contrato geral nao autorizado.');
}

if (!Array.isArray(d.results) || d.results.length !== 2) {
  throw new Error('Quantidade de resultados invalida.');
}

const historical = d.results.find(
  r => r.investigation_version === 1
);

const current = d.results.find(
  r => r.investigation_version === 2
);

if (!historical || !current) {
  throw new Error('Versoes 1 e 2 obrigatorias.');
}

for (const r of [historical, current]) {

  if (
    r.environment !== 'LAB' ||
    r.processor !== 'WF-04' ||
    r.schema_version !== '1.0' ||
    r.dispatch_status !== 'MOCK_ONLY' ||
    r.real_execution_started !== false ||
    r.notification_sent !== false ||
    !r.provenance ||
    r.provenance.version !== r.investigation_version ||
    !/^[a-f0-9]{64}$/.test(
      r.provenance.content_signature || ''
    )
  ) {
    throw new Error('Identidade ou proveniencia invalida.');
  }
}

if (
  historical.queue_id !== 12 ||
  historical.source_event_id !== 'LAB-0001' ||
  historical.status !== 'SKIPPED' ||
  historical.ai_executed !== false ||
  historical.analysis !== null ||
  historical.requires_human_review !== false
) {
  throw new Error('Versao historica nao foi bloqueada.');
}

if (
  current.queue_id !== 13 ||
  current.source_event_id !== 'LAB-0001' ||
  current.investigation_id !== historical.investigation_id ||
  current.status !== 'ANALYSIS_COMPLETED' ||
  current.ai_executed !== true ||
  current.requires_human_review !== true ||
  !current.analysis
) {
  throw new Error('Versao atual nao autorizada.');
}

const a = current.analysis;

if (
  typeof a.summary !== 'string' ||
  !a.summary.trim() ||
  typeof a.assessment !== 'string' ||
  !a.assessment.trim()
) {
  throw new Error('Resumo ou avaliacao ausente.');
}

for (const field of [
  'evidence_ids',
  'limitations',
  'review_actions'
]) {

  if (
    !Array.isArray(a[field]) ||
    !a[field].every(
      v => typeof v === 'string' && v.trim().length > 0
    )
  ) {
    throw new Error('Campo invalido: ' + field);
  }
}

const ids = a.evidence_ids;

if (
  ids.length !== 2 ||
  !ids.includes('LAB-EV-001') ||
  !ids.includes('LAB-EV-002')
) {
  throw new Error('Referencias de evidencias invalidas.');
}

return [{
  json: {
    ...d,
    contract_validation: 'VALID',
    historical_queue_id: historical.queue_id,
    selected_queue_id: current.queue_id,
    selected_version: current.investigation_version,
    selected_signature: current.provenance.content_signature
  }
}];
